function getAmazonQuicksightQTranslation(key, lang) {
    return (amazonquicksightqTranslations[lang] && amazonquicksightqTranslations[lang][key]) ||
           (amazonquicksightqTranslations.en && amazonquicksightqTranslations.en[key]) || null;
}

function applyAmazonQuicksightQTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.amazon-quicksight-q.") || key.startsWith("review.common."))) {
            const translation = getAmazonQuicksightQTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    console.log(`Applied ${count} amazon-quicksight-q translations`);
}

window.addEventListener("languageChanged", e => setTimeout(() => applyAmazonQuicksightQTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyAmazonQuicksightQTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyAmazonQuicksightQTranslations(window.i18n?.getCurrentLanguage() || "en");
}
